import itertools

# Define the coloring
edges = []
# vertices 0..7
# parts: A={0,1,2}, B={3,4,5}, C={6,7}
A = {0,1,2}
B = {3,4,5}
C = {6,7}

def color(i,j):
    # same part -> red (0), different -> blue (1)
    if (i in A and j in A) or (i in B and j in B) or (i in C and j in C):
        return 0
    else:
        return 1

# lexicographic order i<j
edge_list = []
for i in range(8):
    for j in range(i+1,8):
        edge_list.append((i,j))

colors = [color(i,j) for i,j in edge_list]
print("Colors:", colors)
print("Length:", len(colors))

# Verify no monochromatic K4
verts = list(range(8))
for subset in itertools.combinations(verts, 4):
    # count red and blue edges among subset
    red = 0
    blue = 0
    for a,b in itertools.combinations(subset,2):
        c = color(a,b)
        if c == 0:
            red += 1
        else:
            blue += 1
    if red == 6 or blue == 6:
        print("Monochromatic K4 found:", subset, "red:", red, "blue:", blue)
        raise SystemExit
print("No monochromatic K4 found. Valid coloring.")
